export type TKey = keyof typeof STRINGS;

const ORDER: Lang[] = ["fr", "es", "de", "pt", "it", "ar", "tr"];
let current: Lang = "en";

export const isLang = (value: unknown): value is Lang => LANGUAGES.some((item) => item.id === value);

// The interface language. PRIVATE OS sets it from settings at the top of every render, before its
// children render, so every screen below it reads the new language in the same pass. A memo that
// holds translated text lists the language in its dependencies.
export function setLanguage(lang: string) {
  current = isLang(lang) ? lang : "en";
}
export const getLanguage = () => current;

function lookup(entry: Tr7 | Tr8, key: string, lang: Lang): string {
  if (lang === "en") return entry.length === 8 ? entry[0] : key;
  return entry[ORDER.indexOf(lang) + (entry.length === 8 ? 1 : 0)] ?? key;
}

// t("Hi {name}", { name }) -> "Bonjour Hanan". Unknown placeholders are left as they are.
export function t(key: TKey, vars?: Record<string, string | number>, lang: Lang = current): string {
  const text = lookup(STRINGS[key], key, lang);
  return vars ? text.replace(/\{(\w+)\}/g, (match, name: string) => (name in vars ? String(vars[name]) : match)) : text;
}

// For text that is data rather than a fixed key (app names, settings labels): translated when the
// dictionary knows it, otherwise shown as it is.
export function tx(text: string, lang: Lang = current): string {
  const entry = (STRINGS as Record<string, Tr7 | Tr8>)[text];
  return entry ? lookup(entry, text, lang) : text;
}

// "1 window" / "3 windows", with each language's own word.
export const windowsCount = (count: number) => (count === 1 ? t("1 window") : t("{n} windows", { n: count }));

// Upper case that respects the language (Turkish dotted İ, for example).
export const upper = (text: string, lang: Lang = current) => text.toLocaleUpperCase(lang);

// Locale for dates and times.
export const locale = (lang: Lang = current) => (lang === "en" ? "en-GB" : lang);

// The comma after a greeting ("Bonjour," / "صباح الخير،").
export const comma = (lang: Lang = current) => (lang === "ar" ? "،" : ",");

// Arabic reads right to left. Only text containers get this, never the whole OS layout.
export const textDir = (lang: Lang = current): "rtl" | "ltr" => (lang === "ar" ? "rtl" : "ltr");

// The browser's language when it is one of ours, otherwise English.
export function detectLanguage(): Lang {
  if (typeof navigator === "undefined") return "en";
  const list = navigator.languages?.length ? navigator.languages : [navigator.language];
  for (const tag of list) {
    const base = String(tag || "").toLowerCase().split("-")[0];
    if (isLang(base)) return base;
  }
  return "en";
}
